    }

    @Nested
    @DisplayName("Clube da loja")
    class Clube {

        @Test
        void bronzeNaoGanhaNada() {
            ResumoResposta resumo = calculadora.calcular(
                    pedido(CAMISETA, TENIS).entrega("EXPRESSA").montar());

